function NoticeCard({ title, content, elderly }) {
  return (
    <div style={{
      border: "1px solid #ddd",
      borderRadius: "8px",
      padding: "16px",
      marginBottom: "12px"
    }}>
      <h3 style={{ margin: "0 0 8px 0" }}>{title}</h3>
      <p style={{ margin: 0 }}>{content}</p>
      <button style={{
        marginTop: "10px",
        padding: elderly ? "12px 24px" : "6px 12px",
        fontSize: elderly ? "18px" : "14px"
      }}>
        Read More
      </button>
    </div>
  );
}

export default NoticeCard;
